module crazy_town_solver (\n    input clk, rst_n, start,\n    input [8:0] wr_addr,\n    input [62:0] wr_data,\n    input wr_en,\n    input [20:0] x1, y1,\n    input [20:0] x2, y2,\n    input [8:0] n,\n    output [8:0] count,\n    output done\n);\n\n// Internal memory\nreg [62:0] mem [0:299];\n\n// State declarations\nlocalparam [3:0] S_IDLE = 4'd0;\nlocalparam [3:0] S_READ = 4'd1;\nlocalparam [3:0] S_MULT_AX1 = 4'd2;\nlocalparam [3:0] S_MULT_AX2 = 4'd3;\nlocalparam [3:0] S_MULT_BY1 = 4'd4;\nlocalparam [3:0] S_MULT_BY2 = 4'd5;\nlocalparam [3:0] S_ADD1 = 4'd6;\nlocalparam [3:0] S_ADD2 = 4'd7;\nlocalparam [3:0] S_ADD_C1 = 4'd8;\nlocalparam [3:0] S_ADD_C2 = 4'd9;\nlocalparam [3:0] S_CHECK = 4'd10;\nlocalparam [3:0] S_NEXT = 4'd11;\nlocalparam [3:0] S_DONE = 4'd12;\n\nreg [3:0] state;\nreg [8:0] line_index;\nreg [8:0] count_reg;\nreg [20:0] a_reg, b_reg;\nreg signed [20:0] c_reg;\n\n// Intermediate results\nreg signed [41:0] ax1, ax2, by1, by2;\nreg signed [41:0] sum1, sum2;\n\n// Memory write\nalways @(posedge clk) begin\n    if (wr_en) mem[wr_addr] <= wr_data;\nend\n\n// Main FSM\nalways @(posedge clk or negedge rst_n) begin\n    if (!rst_n) begin\n        state <= S_IDLE;\n        count_reg <= 9'd0;\n        line_index <= 9'd0;\n        a_reg <= 21'd0;\n        b_reg <= 21'd0;\n        c_reg <= 21'd0;\n        ax1 <= 42'd0;\n        ax2 <= 42'd0;\n        by1 <= 42'd0;\n        by2 <= 42'd0;\n        sum1 <= 42'd0;\n        sum2 <= 42'd0;\n    end else begin\n        case (state)\n            S_IDLE: begin\n                count_reg <= 9'd0;\n                line_index <= 9'd0;\n                if (start) state <= S_READ;\n            end\n\n            S_READ: begin\n                a_reg <= mem[line_index][62:42];\n                b_reg <= mem[line_index][41:21];\n                c_reg <= mem[line_index][20:0];\n                state <= S_MULT_AX1;\n            end\n\n            // Calculate a*x1\n            S_MULT_AX1: begin\n                ax1 <= $signed({{21{a_reg[20]}}, a_reg}) * $signed({{21{x1[20]}}, x1});\n                state <= S_MULT_AX2;\n            end\n\n            // Calculate a*x2\n            S_MULT_AX2: begin\n                ax2 <= $signed({{21{a_reg[20]}}, a_reg}) * $signed({{21{x2[20]}}, x2});\n                state <= S_MULT_BY1;\n            end\n\n            // Calculate b*y1\n            S_MULT_BY1: begin\n                by1 <= $signed({{21{b_reg[20]}}, b_reg}) * $signed({{21{y1[20]}}, y1});\n                state <= S_MULT_BY2;\n            end\n\n            // Calculate b*y2\n            S_MULT_BY2: begin\n                by2 <= $signed({{21{b_reg[20]}}, b_reg}) * $signed({{21{y2[20]}}, y2});\n                state <= S_ADD1;\n            end\n\n            // Add ax1 + by1\n            S_ADD1: begin\n                sum1 <= ax1 + by1;\n                state <= S_ADD2;\n            end\n\n            // Add ax2 + by2\n            S_ADD2: begin\n                sum2 <= ax2 + by2;\n                state <= S_ADD_C1;\n            end\n\n            // Add c to sum1\n            S_ADD_C1: begin\n                sum1 <= sum1 + {21'd0, c_reg};\n                state <= S_ADD_C2;\n            end\n\n            // Add c to sum2\n            S_ADD_C2: begin\n                sum2 <= sum2 + {21'd0, c_reg};\n                state <= S_CHECK;\n            end\n\n            S_CHECK: begin\n                if ((sum1[41] != sum2[41])) count_reg <= count_reg + 1'd1;\n                state <= S_NEXT;\n            end\n\n            S_NEXT: begin\n                line_index <= line_index + 1'd1;\n                if (line_index == n) state <= S_DONE;\n                else state <= S_READ;\n            end\n\n            S_DONE: begin\n                if (!start) state <= S_IDLE;\n            end\n\n            default: state <= S_IDLE;\n        endcase\n    end\nend\n\n// Output assignments\nassign count = count_reg;\nassign done = (state == S_DONE);\n\nendmodule